//! process, signed with the `SECRET_KEY_BASE` in `vectors/test.env`. Each test boots the app over
//! a private copy of one.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, SystemTime};

const ROOT: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../..");

/// A value from `vectors/test.env`.
pub fn test_env(name: &str) -> String {
    let env = std::fs::read_to_string(Path::new(ROOT).join("vectors/test.env")).expect("vectors/test.env");
    env.lines()
        .find_map(|line| line.strip_prefix(&format!("{name}=")).map(str::to_string))
        .unwrap_or_else(|| panic!("{name} isn't in vectors/test.env"))
}

/// Seed `name`, built the first time a test asks for it: a directory with `db/production.sqlite3`,
/// `db/labels.json` and the disk service's `files/`. Tests copy it, never change it.
pub fn seed_dir(name: &str) -> PathBuf {
    static BUILT: Mutex<BTreeMap<String, PathBuf>> = Mutex::new(BTreeMap::new());
    let mut built = BUILT.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
    if let Some(dir) = built.get(name) {
        return dir.clone();
    }
    let dir = seeds_dir().join(name);
    let _ = std::fs::remove_dir_all(&dir);
    let storage = crate::config::StoragePaths::new(&dir, "production");
    crate::seed::build(name, &storage, "production", &test_env("SECRET_KEY_BASE"))
        .unwrap_or_else(|e| panic!("building seed {name}: {e:#}"));
    built.insert(name.to_string(), dir.clone());
    dir
}

/// `labels.json` of a seed: `table.label` -> id, and the strings tests need.
pub fn seed_labels(seed: &Path) -> serde_json::Value {
    serde_json::from_str(&std::fs::read_to_string(seed.join("db/labels.json")).unwrap()).unwrap()
}

/// Copies seed `name` into `storage` (a `CAMPFIRE_STORAGE_PATH`): its database and files.
pub fn copy_seed(name: &str, storage: &Path) -> PathBuf {
    let seed = seed_dir(name);
    std::fs::create_dir_all(storage.join("db")).unwrap();
    std::fs::copy(seed.join("db/production.sqlite3"), storage.join("db/production.sqlite3")).unwrap();
    copy_dir(&seed.join("files"), &storage.join("files"));
    seed
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for entry in std::fs::read_dir(from).unwrap().flatten() {
        let target = to.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
"
}

