use rusqlite::{Connection, params};

use crate::database::Tx;
use crate::error::{OptionalExt, Result};
use crate::models::User;
use crate::sql::{self, CachedStatements, columns, query_all, query_one};
use crate::time::Timestamp;

#[derive(Debug, Clone, PartialEq)]
pub struct Bot {
    pub id: i64,
    pub user_id: i64,
    pub creator_id: i64,
    pub code: String,
    pub webhook_url: Option<String>,
    pub created_at: Timestamp,
    pub updated_at: Timestamp,
}

columns! {
    Bot, "bots", bot_columns {
        id: "id",
        user_id: "user_id",
        creator_id: "creator_id",
        code: "code",
        webhook_url: "webhook_url",
        created_at: "created_at",
        updated_at: "updated_at",
    }
}

impl Bot {
    pub fn find(conn: &Connection, id: i64) -> Result<Self> {
        query_one(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."id" = ? LIMIT 1"#),
            [id],
            Self::from_row,
        )?
        .or_not_found("Bot")
    }

    pub fn find_by_id(conn: &Connection, id: i64) -> Result<Option<Self>> {
        query_one(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."id" = ? LIMIT 1"#),
            [id],
            Self::from_row,
        )
    }

    pub fn find_by_code(conn: &Connection, code: &str) -> Result<Option<Self>> {
        query_one(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."code" = ? LIMIT 1"#),
            [code],
            Self::from_row,
        )
    }

    pub fn find_by_user_id(conn: &Connection, user_id: i64) -> Result<Option<Self>> {
        query_one(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."user_id" = ? LIMIT 1"#),
            [user_id],
            Self::from_row,
        )
    }

    pub fn all(conn: &Connection) -> Result<Vec<Self>> {
        query_all(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" ORDER BY "bots"."created_at" ASC"#),
            [],
            Self::from_row,
        )
    }

    pub fn for_creator(conn: &Connection, creator_id: i64) -> Result<Vec<Self>> {
        query_all(
            conn,
            concat!("SELECT ", bot_columns!(), r#" FROM "bots" WHERE "bots"."creator_id" = ? ORDER BY "bots"."created_at" ASC"#),
            [creator_id],
            Self::from_row,
        )
    }

    pub fn for_room_with_webhook(conn: &Connection, room_id: i64) -> Result<Vec<(Self, User)>> {
        use crate::models::user::user_columns;
        let sql = concat!(
            "SELECT ",
            bot_columns!(),
            ", ",
            user_columns!(),
            r#" FROM "bots"
            INNER JOIN "users" ON "bots"."user_id" = "users"."id"
            INNER JOIN "memberships" ON "bots"."user_id" = "memberships"."user_id"
            WHERE "memberships"."room_id" = ?
              AND "users"."status" = 0
              AND "bots"."webhook_url" IS NOT NULL
              AND "bots"."webhook_url" != ''"#
        );
        let mut stmt = conn.prepare_cached(sql)?;
        let rows = stmt.query_map([room_id], |row| {
            let bot = Bot::from_row_at(row, 0)?;
            let user = User::from_row_at(row, Bot::COLUMNS.len())?;
            Ok((bot, user))
        })?;
        let mut list = Vec::new();
        for r in rows {
            list.push(r?);
        }
        Ok(list)
    }

    pub fn generate_code() -> String {
        sql::base58(24)
    }

    pub fn create(tx: &mut Tx<'_>, user_id: i64, creator_id: i64, code: &str, webhook_url: Option<&str>) -> Result<Self> {
        let now = tx.now();
        let id: i64 = tx.conn().query_row_cached(
            r#"INSERT INTO "bots" ("user_id", "creator_id", "code", "webhook_url", "created_at", "updated_at") VALUES (?, ?, ?, ?, ?, ?) RETURNING "id""#,
            params![user_id, creator_id, code, webhook_url, now, now],
            |r| r.get(0),
        )?;
        Ok(Self {
            id,
            user_id,
            creator_id,
            code: code.to_string(),
            webhook_url: webhook_url.map(str::to_string),
            created_at: now,
            updated_at: now,
        })
    }

    pub fn update(&mut self, tx: &mut Tx<'_>, webhook_url: Option<Option<&str>>) -> Result<()> {
        if let Some(webhook_url) = webhook_url {
            let webhook_url = webhook_url.map(str::to_string);
            if self.webhook_url != webhook_url {
                let now = tx.now();
                self.webhook_url = webhook_url;
                self.updated_at = now;
                tx.conn().execute_cached(
                    r#"UPDATE "bots" SET "webhook_url" = ?, "updated_at" = ? WHERE "bots"."id" = ?"#,
                    params![self.webhook_url, now, self.id],
                )?;
            }
        }
        Ok(())
    }

    pub fn destroy(&self, tx: &mut Tx<'_>) -> Result<()> {
        tx.conn().execute_cached(r#"DELETE FROM "bots" WHERE "bots"."id" = ?"#, [self.id])?;
        Ok(())
    }
}
