    let user_ids: Vec<i64> = query_all(tx.conn(), r#"SELECT "users"."id" FROM "users" WHERE "users"."status" = ?"#, [0], |r| r.get(0))?;
    let room = Room::find(tx.conn(), room_id)?;
    insert_memberships(tx, room_id, room.default_involvement(), &user_ids)
}
