    let bot_user_id = bot_user.id;
    let code_clone = code.clone();
    let bot = t.write(move |tx| Bot::create(tx, bot_user_id, creator_id, &code_clone, Some("https://example.com/webhook"), false));
    assert_eq!(bot.user_id, bot_user.id);
    assert_eq!(bot.creator_id, creator_id);
    assert_eq!(bot.code, code);
    assert_eq!(bot.webhook_url, Some("https://example.com/webhook".to_string()));
    assert!(!bot.all_open_rooms);

    // Finders
    let bot_id = bot.id;
    let found = t.read(move |c| Bot::find(c, bot_id));
    assert_eq!(found, bot);

    let code_clone = code.clone();
    let found_by_code = t.read(move |c| Bot::find_by_code(c, &code_clone)).unwrap();
    assert_eq!(found_by_code, bot);

    let found_by_user = t.read(move |c| Bot::find_by_user_id(c, bot_user.id)).unwrap();
    assert_eq!(found_by_user, bot);

    let bots = t.read(move |c| Bot::for_creator(c, creator_id));
    assert!(bots.iter().any(|b| b.id == bot.id));

    let all = t.read(Bot::all);
    assert!(all.iter().any(|b| b.id == bot.id));

    // Update webhook_url and all_open_rooms
    let mut bot_clone = bot.clone();
    let bot_clone = t.write(move |tx| {
        bot_clone.update(tx, Some(Some("https://example.com/updated_hook")), Some(true))?;
        Ok(bot_clone)
    });
    assert_eq!(bot_clone.webhook_url, Some("https://example.com/updated_hook".to_string()));
    assert!(bot_clone.all_open_rooms);
    let found = t.read(move |c| Bot::find(c, bot_id));
    assert_eq!(found.webhook_url, Some("https://example.com/updated_hook".to_string()));
    assert!(found.all_open_rooms);

    // Remove webhook_url
    let mut bot_clone = bot_clone;
    let bot_clone = t.write(move |tx| {
        bot_clone.update(tx, Some(None), None)?;
        Ok(bot_clone)
    });
    assert_eq!(bot_clone.webhook_url, None);
    let found = t.read(move |c| Bot::find(c, bot_id));
    assert_eq!(found.webhook_url, None);

    // Destroy
    let bot_clone = bot_clone;
    t.write(move |tx| bot_clone.destroy(tx));
    assert!(t.read(move |c| Bot::find_by_id(c, bot_id)).is_none());
    assert!(t.read(move |c| Bot::find_by_code(c, &code)).is_none());
}
