    assert_eq!(reply.status, StatusCode::OK);
    assert!(!reply.text().contains("Deploy Bot"), "member should not see other members bots");

    // 8. Jason cannot edit Kevin's bot
    let reply = jz.get(&format!("/bots/{}/edit", bot.id)).await;
    assert_eq!(reply.status, StatusCode::FORBIDDEN);

    // 9. Kevin edits the bot
    let reply = kevin.get(&format!("/bots/{}/edit", bot.id)).await;
    assert_eq!(reply.status, StatusCode::OK);
    let html = reply.text();
    assert!(html.contains("Name the bot"), "{html}");
    assert!(html.contains("Save changes"), "{html}");
    assert!(html.contains("Add to all open rooms"), "{html}");
    assert!(html.contains("Delete this chat bot"), "{html}");

    // Kevin updates bot name to "CI Bot" and turns switch ON
    let reply = kevin
        .send(
            Req::new(Method::PATCH, &format!("/bots/{}", bot.id))
                .form(&[("bot[name]", "CI Bot"), ("bot[all_open_rooms]", "1")]),
        )
        .await;
    assert_eq!(reply.status, StatusCode::FOUND);

    let in_hq = app.db().read({
        let user_id = bot.user_id;
        move |conn| Membership::find_by_room_and_user(conn, HQ, user_id)
    }).await.unwrap();
    assert!(in_hq.is_some(), "bot joins open room HQ when switch is turned on");

    // Kevin edits bot to turn switch OFF -> keeps existing memberships
    let reply = kevin
        .send(
            Req::new(Method::PATCH, &format!("/bots/{}", bot.id))
                .form(&[("bot[name]", "CI Bot"), ("bot[all_open_rooms]", "0")]),
        )
        .await;
    assert_eq!(reply.status, StatusCode::FOUND);

    let in_hq = app.db().read({
        let user_id = bot.user_id;
        move |conn| Membership::find_by_room_and_user(conn, HQ, user_id)
    }).await.unwrap();
    assert!(in_hq.is_some(), "bot keeps memberships when switch is turned off");

    let reply = kevin.get("/bots").await;
    assert!(reply.text().contains("CI Bot"));
    assert!(reply.text().contains("Edit CI Bot"));

    // 10. Kevin deletes the bot
    let reply = kevin
        .send(Req::new(Method::DELETE, &format!("/bots/{}", bot.id)))
        .await;
    assert_eq!(reply.status, StatusCode::FOUND);
    assert_eq!(reply.location(), Some("http://campfire.test/bots"));

    let reply = kevin.get("/bots").await;
    assert!(!reply.text().contains("CI Bot"));

    // Deleted bot can no longer post
    let reply = app.anonymous().send(
        Req::new(Method::POST, &format!("/rooms/{HQ}/{bot_code}/messages"))
            .header("content-type", "application/x-www-form-urlencoded")
    ).await;
    assert_eq!(reply.status, StatusCode::UNAUTHORIZED);
}

#[tokio::test]
async fn bot_posting_api() {
    let app = TestApp::boot().await;
    let mut david = app.david();

    // Create a bot with all open rooms enabled
    david.send(Req::new(Method::POST, "/bots").form(&[("bot[name]", "Release Bot"), ("bot[all_open_rooms]", "1")])).await;
    let reply = david.get("/bots").await;
    let html = reply.text();
    let code_needle = "name=\"bot_code\" value=\"";
    let start = html.find(code_needle).expect("bot code input").to_owned() + code_needle.len();
    let end = start + html[start..].find('"').unwrap();
    let bot_code = html[start..end].to_string();

    let mut client = app.anonymous();

    // 1. Post message successfully (201 Created)
    let body = "Deploy of v1.2.3 finished ✅";
    let mut req = Req::new(Method::POST, &format!("/rooms/{HQ}/{bot_code}/messages"));
    req.body = body.as_bytes().to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::CREATED);
    let location = reply.location().expect("location header");
    assert!(location.starts_with("/messages/"), "Location was {location}");

    // Message shows bot name as author
    let message_id: i64 = location.strip_prefix("/messages/").unwrap().parse().unwrap();
    let msg = app.db().read(move |conn| Message::find(conn, message_id)).await.unwrap();
    let author = app.db().read(move |conn| User::find(conn, msg.creator_id)).await.unwrap();
    assert_eq!(author.name, "Release Bot");

    // 2. Empty body -> 422 Unprocessable Content
    let mut req = Req::new(Method::POST, &format!("/rooms/{HQ}/{bot_code}/messages"));
    req.body = b"".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::UNPROCESSABLE_ENTITY);

    let mut req = Req::new(Method::POST, &format!("/rooms/{HQ}/{bot_code}/messages"));
    req.body = b"   \n  \t  ".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::UNPROCESSABLE_ENTITY);

    // 3. Bad room id -> 404 Not Found
    let mut req = Req::new(Method::POST, &format!("/rooms/999999999/{bot_code}/messages"));
    req.body = b"hello".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::NOT_FOUND);

    let mut req = Req::new(Method::POST, &format!("/rooms/bad-room/{bot_code}/messages"));
    req.body = b"hello".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::NOT_FOUND);

    // 4. Invalid bot code -> 401 Unauthorized
    let mut req = Req::new(Method::POST, &format!("/rooms/{HQ}/invalidcode123/messages"));
    req.body = b"hello".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::UNAUTHORIZED);

    // 5. Bot not a member of closed room -> 404 Not Found
    let mut req = Req::new(Method::POST, &format!("/rooms/{ALL_TALK}/{bot_code}/messages"));
    req.body = b"hello in closed room".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::NOT_FOUND);

    // Now add bot to the closed room (ALL_TALK)
    let bot = app.db().read({
        let code = bot_code.clone();
        move |conn| Bot::find_by_code(conn, &code)
    }).await.unwrap().unwrap();
    app.db().write({
        let user_id = bot.user_id;
        move |tx| {
            let room = Room::find(tx.conn(), ALL_TALK)?;
            room.grant_to(tx, &[user_id])
        }
    }).await.unwrap();

    // Now bot can post to ALL_TALK!
    let mut req = Req::new(Method::POST, &format!("/rooms/{ALL_TALK}/{bot_code}/messages"));
    req.body = b"hello now I am a member".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = client.send(req).await;
    assert_eq!(reply.status, StatusCode::CREATED);
}

