        )
        .await;

    let payload = tokio::time::timeout(std::time::Duration::from_secs(5), rx_payload)
        .await
        .expect("webhook received")
        .expect("channel open");

    let reply_to = payload["room"]["reply_to"].as_str().expect("reply_to string");
    assert_eq!(reply_to, format!("/rooms/{HQ}/{}/messages", bot.code));

    // Now bot replies asynchronously by posting to reply_to
    let mut async_client = app.anonymous();
    let mut req = Req::new(Method::POST, reply_to);
    req.body = b"Finished background task out-of-band!".to_vec();
    req = req.header("content-type", "application/x-www-form-urlencoded");
    let reply = async_client.send(req).await;
    assert_eq!(reply.status, StatusCode::CREATED);

    // Verify message appears in room
    let messages = app.db().read(|conn| Message::last_page(conn, HQ)).await.unwrap();
    let msg = messages.iter().find(|m| m.creator_id == bot.user_id).expect("async message exists");
    let rich_text = app.booted.app.db.env().rich_text.clone();
    let text = app.db().read({
        let msg = msg.clone();
        move |conn| msg.plain_text_body(conn, &*rich_text)
    }).await.unwrap();
    assert!(text.contains("Finished background task out-of-band!"));
}

#[tokio::test]
async fn bot_open_room_membership_switch_and_creation_behavior() {
    let app = TestApp::boot().await;
    let mut david = app.david();

    // 1. Visit /bots/new and verify "Add to all open rooms" switch is off by default
    let reply = david.get("/bots/new").await;
    assert_eq!(reply.status, StatusCode::OK);
    let html = reply.text();
    assert!(html.contains("Add to all open rooms"), "contains switch label: {html}");
    // Should not have checked
    assert!(!html.contains("checked"), "switch should be off by default");

    // 2. Create bot with switch OFF (default)
    david.send(Req::new(Method::POST, "/bots").form(&[("bot[name]", "Selective Bot")])).await;
    let bot_id = app.db().read(|conn| {
        let bots = Bot::all(conn)?;
        Ok(bots.into_iter().find(|b| b.name(conn).unwrap_or_default() == "Selective Bot").unwrap().id)
    }).await.unwrap();

    let bot = app.db().read(move |conn| Bot::find(conn, bot_id)).await.unwrap();
    assert!(!bot.all_open_rooms);

    // Bot is NOT in open rooms (HQ, etc.)
    let in_hq = app.db().read({
        let user_id = bot.user_id;
        move |conn| Membership::find_by_room_and_user(conn, HQ, user_id)
    }).await.unwrap();
    assert!(in_hq.is_none(), "bot should not be in HQ");

    // 3. Regular user (person) created STILL joins open rooms by default
    let person = app.db().write(|tx| {
        User::create(tx, campfire_db::NewUser {
            name: "New Person".into(),
            email_address: Some("person@example.com".into()),
            role: campfire_db::Role::Member,
            ..Default::default()
        })
    }).await.unwrap();

    let person_in_hq = app.db().read({
        let user_id = person.id;
        move |conn| Membership::find_by_room_and_user(conn, HQ, user_id)
    }).await.unwrap();
    assert!(person_in_hq.is_some(), "person still joins open rooms by default");

    // 4. Create a bot with switch ON
    david.send(Req::new(Method::POST, "/bots").form(&[
        ("bot[name]", "Global Bot"),
        ("bot[all_open_rooms]", "1"),
    ])).await;
    let global_bot = app.db().read(|conn| {
        let bots = Bot::all(conn)?;
        Ok(bots.into_iter().find(|b| b.name(conn).unwrap_or_default() == "Global Bot").unwrap())
    }).await.unwrap();
    assert!(global_bot.all_open_rooms);

    // Global Bot IS in HQ
    let global_in_hq = app.db().read({
        let user_id = global_bot.user_id;
        move |conn| Membership::find_by_room_and_user(conn, HQ, user_id)
    }).await.unwrap();
    assert!(global_in_hq.is_some(), "global bot is in HQ");

    // 5. Create a new open room later -> global bot automatically joins it, selective bot does not
    let new_room = app.db().write(|tx| {
        Room::create(tx, RoomType::Open, Some("Engineering"), 1)
    }).await.unwrap();

    let global_in_eng = app.db().read({
        let user_id = global_bot.user_id;
        let room_id = new_room.id;
        move |conn| Membership::find_by_room_and_user(conn, room_id, user_id)
    }).await.unwrap();
    assert!(global_in_eng.is_some(), "global bot joins new open room");

    let selective_in_eng = app.db().read({
        let user_id = bot.user_id;
        let room_id = new_room.id;
        move |conn| Membership::find_by_room_and_user(conn, room_id, user_id)
    }).await.unwrap();
    assert!(selective_in_eng.is_none(), "selective bot does not join new open room");

    // 6. Turn switch OFF for Global Bot -> keeps existing memberships
    let reply = david.get(&format!("/bots/{}/edit", global_bot.id)).await;
    let html = reply.text();
    assert!(html.contains("checked"), "switch is checked on edit page: {html}");

    david.send(Req::new(Method::PATCH, &format!("/bots/{}", global_bot.id)).form(&[
        ("bot[name]", "Global Bot"),
        ("bot[all_open_rooms]", "0"),
    ])).await;

    // Existing memberships kept
    let global_in_eng = app.db().read({
        let user_id = global_bot.user_id;
        let room_id = new_room.id;
        move |conn| Membership::find_by_room_and_user(conn, room_id, user_id)
    }).await.unwrap();
    assert!(global_in_eng.is_some(), "turning switch off keeps current memberships");

    // 7. Create another open room -> former global bot does NOT join it
    let later_room = app.db().write(|tx| {
        Room::create(tx, RoomType::Open, Some("Design"), 1)
    }).await.unwrap();

    let global_in_design = app.db().read({
        let user_id = global_bot.user_id;
        let room_id = later_room.id;
        move |conn| Membership::find_by_room_and_user(conn, room_id, user_id)
    }).await.unwrap();
    assert!(global_in_design.is_none(), "bot with switch off does not join subsequent open rooms");
}

#[tokio::test]
async fn bot_joined_webhook_payload_and_sync_reply() {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    use tokio::net::TcpListener;
    use tokio::sync::mpsc;

    let app = TestApp::boot().await;
    let mut david = app.david();

    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let port = listener.local_addr().unwrap().port();
    let (tx_payload, mut rx_payload) = mpsc::unbounded_channel::<serde_json::Value>();

    tokio::spawn(async move {
        while let Ok((mut stream, _)) = listener.accept().await {
            let mut buf = vec![0u8; 8192];
            let n = stream.read(&mut buf).await.unwrap();
            let req_str = String::from_utf8_lossy(&buf[..n]).to_string();

            if let Some(pos) = req_str.find("\r\n\r\n") {
                let body = &req_str[pos + 4..];
                if let Ok(json) = serde_json::from_str::<serde_json::Value>(body) {
                    let _ = tx_payload.send(json.clone());

                    // If joined event, reply with 200 OK text/plain greeting!
                    if json["event"] == "joined" {
                        let greeting = "Hello everyone! Happy to be here.";
                        let response = format!(
                            "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=utf-8\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                            greeting.len(),
                            greeting
                        );
                        let _ = stream.write_all(response.as_bytes()).await;
                        continue;
                    }

                    let response = "HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n";
                    let _ = stream.write_all(response.as_bytes()).await;
                }
            }
        }
    });

    let webhook_url = format!("http://127.0.0.1:{port}/joined-webhook");

    // 1. Create bot with webhook_url and "Add to all open rooms" switch OFF
    david.send(Req::new(Method::POST, "/bots").form(&[
        ("bot[name]", "Friendly Bot"),
        ("bot[webhook_url]", &webhook_url),
    ])).await;

    let bot = app.db().read(|conn| {
        let bots = Bot::all(conn)?;
        Ok(bots.into_iter().find(|b| b.name(conn).unwrap_or_default() == "Friendly Bot").unwrap())
    }).await.unwrap();

    // No joined event yet since it didn't join any rooms
    tokio::time::sleep(std::time::Duration::from_millis(200)).await;
    assert!(rx_payload.try_recv().is_err());

    // 2. Direct conversations NEVER trigger joined
    app.db().write({
        let bot_user_id = bot.user_id;
        move |tx| {
            Room::find_or_create_direct_for(tx, &[1, bot_user_id], 1)
        }
    }).await.unwrap();

    tokio::time::sleep(std::time::Duration::from_millis(200)).await;
    assert!(rx_payload.try_recv().is_err(), "direct rooms never trigger joined event");

    // 3. Adding bot to a closed room triggers `joined` event
    let closed_room = app.db().write({
        let bot_user_id = bot.user_id;
        move |tx| {
            Room::create_for(tx, RoomType::Closed, Some("Ops"), 1, &[1, bot_user_id])
        }
    }).await.unwrap();

    let payload = tokio::time::timeout(std::time::Duration::from_secs(5), rx_payload.recv())
        .await
        .expect("joined webhook received")
        .expect("channel open");

    assert_eq!(payload["event"], "joined");
    assert_eq!(payload["room"]["id"], closed_room.id);
    assert_eq!(payload["room"]["name"], "Ops");
    assert_eq!(payload["room"]["reply_to"], format!("/rooms/{}/{}/messages", closed_room.id, bot.code));

    // Verify synchronous greeting message was posted into Ops by Friendly Bot
    let mut greeting_posted = false;
    for _ in 0..50 {
        tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        let messages = app.db().read({
            let room_id = closed_room.id;
            move |conn| Message::last_page(conn, room_id)
        }).await.unwrap();
        if messages.iter().any(|m| m.creator_id == bot.user_id) {
            greeting_posted = true;
            let msg = messages.iter().find(|m| m.creator_id == bot.user_id).unwrap();
            let rich_text = app.booted.app.db.env().rich_text.clone();
            let text = app.db().read({
                let msg = msg.clone();
                move |conn| msg.plain_text_body(conn, &*rich_text)
            }).await.unwrap();
            assert!(text.contains("Hello everyone! Happy to be here."));
            break;
        }
    }
    assert!(greeting_posted, "greeting posted in closed room");

    // 4. Updating the closed room does NOT trigger joined again (exactly once per room)
    app.db().write({
        let room_id = closed_room.id;
        let bot_user_id = bot.user_id;
        move |tx| {
            let mut room = Room::find(tx.conn(), room_id)?;
            room.update(tx, Some("Ops Renamed"), None)?;
            room.grant_to(tx, &[bot_user_id])
        }
    }).await.unwrap();

    tokio::time::sleep(std::time::Duration::from_millis(200)).await;
    assert!(rx_payload.try_recv().is_err(), "no duplicate joined event for same room");

    // 5. Enabling "Add to all open rooms" on edit triggers joined for open rooms (e.g. HQ)
    david.send(Req::new(Method::PATCH, &format!("/bots/{}", bot.id)).form(&[
        ("bot[name]", "Friendly Bot"),
        ("bot[all_open_rooms]", "1"),
    ])).await;

    let payload = tokio::time::timeout(std::time::Duration::from_secs(5), rx_payload.recv())
        .await
        .expect("joined webhook received for HQ")
        .expect("channel open");

    assert_eq!(payload["event"], "joined");
    assert_eq!(payload["room"]["id"], HQ);
    assert_eq!(payload["room"]["name"], "HQ");
    assert_eq!(payload["room"]["reply_to"], format!("/rooms/{HQ}/{}/messages", bot.code));
}

